// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Threat_Qualification_supervisor_process_threat_qualification_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification)
  }

  /** helper function to set the values of all input ports.
   * @param raw_threat payload for data port raw_threat
   */
  def put_concrete_inputs(raw_threat : Mining_Threat_Retreat_Supervisor.Threat_Observation): Unit = {
    put_raw_threat(raw_threat)
  }


  /** helper function to check Threat_Qualification_supervisor_process_threat_qualification's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param qualified_threat method that will be called with the value of the outgoing data
   *        port 'qualified_threat'.
   */
  def check_concrete_output(qualified_threat: Mining_Threat_Retreat_Supervisor.Threat_Observation => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val qualified_threatValue: Mining_Threat_Retreat_Supervisor.Threat_Observation = get_qualified_threat().get
    if(!qualified_threat(qualified_threatValue)) {
      testFailures = testFailures :+ st"'qualified_threat' did not match expected: value of the outgoing data port is ${qualified_threatValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_raw_threat(value : Mining_Threat_Retreat_Supervisor.Threat_Observation): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification.operational_api.raw_threat_Id, Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload(value))
  }

  // getter for out DataPort
  def get_qualified_threat(): Option[Mining_Threat_Retreat_Supervisor.Threat_Observation] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Threat_Observation] = get_qualified_threat_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port qualified_threat.  Expecting 'Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Threat_Observation]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_qualified_threat_payload(): Option[Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_System_Instance_supervisor_process_threat_qualification.initialization_api.qualified_threat_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Threat_Observation_Payload]]
  }

}
